<script setup lang="ts">
import QualificationWarnings from './QualificationWarnings.vue';
import {ref,onMounted,computed} from 'vue';import {onShow} from '@dcloudio/uni-app';import AppPage from '../AppPage.vue';import AppNavbar from '@/components/AppNavbar.vue';import BaseCard from '@/components/BaseCard.vue';import AppButton from '@/components/AppButton.vue';import SectionHeader from '@/components/SectionHeader.vue';import StatusTag from '@/components/StatusTag.vue';import Stage1Status from './Stage1Status.vue';import {useStage1Page} from '../../services/use-stage1-page';import {stage1Service,label} from '../../services/stage1';import type {Data} from '../../services/stage1'
const props=defineProps<{cooperation?:boolean}>(),p=useStage1Page('eligibility'),{error,loading}=p,data=ref<Data|null>(null)
const tiers=[{key:'BASIC',flag:'BASIC_ELIGIBLE',title:'基础经营条件'},{key:'MOCK',flag:'MOCK_READY',title:'模拟模式前置条件'},{key:'REAL',flag:'REAL_READY',title:'真实渠道前置条件'}]
const currentEligibility=computed(()=>data.value?(props.cooperation?data.value.eligibility:data.value):null)
function load(){return p.read(()=>props.cooperation?stage1Service.read<Data>('/cooperation'):stage1Service.eligibility(),v=>{data.value=v})}
function repair(code:string){if(code==='LICENSE_EXPIRED'&&p.has('profile.read'))return {path:'/pages/qualifications/index',label:p.has('profile.write')?'查看并续期资质':'查看资质'};if((code.startsWith('AGREEMENT_')||code.startsWith('RULE_'))&&p.has('cooperation.read'))return {path:'/pages/cooperation/status/index',label:'查看协议与规则'};if(code==='STORE_INACTIVE'&&p.has('profile.read'))return {path:'/pages/profile/basic/index',label:'查看店铺资料'};return null}
function repairGo(code:string){const target=repair(code);if(target)go(target.path)}
function go(path:string){uni.navigateTo({url:path})}
async function preview(id:string){try{const local=await stage1Service.preview(id);uni.openDocument({filePath:local,showMenu:false,fail:()=>uni.previewImage({urls:[local]})})}catch(e){error.value=e instanceof Error?e.message:'附件读取失败'}}
onMounted(load);onShow(()=>{if(data.value)void load()})
</script>
<template><AppPage secondary :status="loading&&!data?'loading':'ready'"><template #navbar><AppNavbar :title="cooperation?'合作协议与规则':'经营资格'" centered show-back/></template><view class="s1-eligibility stack"><Stage1Status :error="error"/><template v-if="data&&!error"><BaseCard><SectionHeader title="当前资格"/><text class="s1-copy">计算时间：{{(cooperation?data.eligibility:data).evaluatedAt}}</text><text class="s1-copy">{{(cooperation?data.eligibility:data).environment}} / {{(cooperation?data.eligibility:data).authorizedMode}}</text><text v-if="(cooperation?data.eligibility:data).validUntil" class="s1-copy">下一条件边界：{{(cooperation?data.eligibility:data).validUntil}}</text><QualificationWarnings :items="currentEligibility?.qualificationWarnings"/></BaseCard><BaseCard v-for="tier in tiers" :key="tier.key" class="s1-tier"><SectionHeader :title="tier.title"/><StatusTag :tone="(cooperation?data.eligibility:data)[tier.flag]?'success':'pending'">{{(cooperation?data.eligibility:data)[tier.flag]?'条件满足':'待完善'}}</StatusTag><view v-for="(reason,index) in (cooperation?data.eligibility:data).reasons[tier.key]" :key="index" class="s1-reason"><text>{{label(reason.code)}}</text><text v-if="reason.objectId" class="s1-copy">来源 {{reason.objectId}}</text><AppButton v-if="repair(reason.code)&&!(cooperation&&repair(reason.code)?.path==='/pages/cooperation/status/index')" variant="quiet" @click="repairGo(reason.code)">{{repair(reason.code)?.label}}</AppButton><text v-else class="s1-copy">请联系负责此项的平台人员核查。</text></view></BaseCard><BaseCard v-for="category in currentEligibility?.categories||[]" :key="category.categoryId" class="s1-tier"><SectionHeader :title="'经营类目 '+(category.categoryName||category.categoryId)"/><text class="s1-copy">类目条件独立判断，店铺基础条件满足不代表全部类目可售。</text><view v-for="tier in tiers" :key="tier.key"><text>{{tier.title}}：</text><StatusTag :tone="category[tier.flag]?'success':'pending'">{{category[tier.flag]?'条件满足':'待完善'}}</StatusTag><view v-for="(reason,index) in category.reasons[tier.key]" :key="index" class="s1-reason"><text>{{label(reason.code)}}</text><text class="s1-copy">来源 {{reason.objectId}}</text><AppButton v-if="repair(reason.code)&&!(cooperation&&repair(reason.code)?.path==='/pages/cooperation/status/index')" variant="quiet" @click="repairGo(reason.code)">{{repair(reason.code)?.label}}</AppButton><text v-else class="s1-copy">请联系负责此项的平台人员核查。</text></view></view></BaseCard><BaseCard v-if="cooperation" v-for="agreement in data.agreements" :key="agreement.id" class="s1-agreement"><SectionHeader :title="agreement.payload.name"/><StatusTag>{{label(agreement.status)}} · 版本 {{agreement.revision}}</StatusTag><text>协议编号 {{agreement.number}}</text><text>{{agreement.payload.platformLegalName}} / {{agreement.payload.merchantLegalName}}</text><text>{{agreement.payload.startDate}} 至 {{agreement.payload.endDate}}（含当日）</text><text>佣金比例 {{agreement.payload.rateBps/100}}%</text><text>{{agreement.payload.commissionClause}}</text><text>{{agreement.payload.refundSummary}}</text><AppButton v-for="id in agreement.payload.fileIds" :key="id" variant="quiet" @click="preview(id)">预览协议附件</AppButton></BaseCard><BaseCard v-if="cooperation" v-for="rule in data.rules" :key="rule.id" class="s1-agreement"><SectionHeader :title="rule.payload.name"/><StatusTag>{{label(rule.status)}} · 版本 {{rule.revision}}</StatusTag><text>引用协议 {{rule.agreementId}} / {{rule.agreementRevision}}</text><text>{{rule.payload.startDate}} 至 {{rule.payload.endDate}}</text><text>佣金比例 {{rule.payload.rateBps/100}}%，以商品实付金额（不含运费）为基数，向下取整至分。</text><text>{{rule.payload.commissionClause}}</text><text class="s1-copy">本阶段只展示规则，未执行资金计算或划转。</text></BaseCard></template><AppButton variant="secondary" :loading="loading" @click="load">重新核查</AppButton><AppButton v-if="p.has('profile.read')" variant="quiet" @click="go('/pages/qualifications/index')">查看资质与续期</AppButton><AppButton v-if="!cooperation&&p.has('cooperation.read')" variant="quiet" @click="go('/pages/cooperation/status/index')">查看合作协议</AppButton></view></AppPage></template>
<style scoped lang="scss">.s1-eligibility{padding:$space-4 $page-gutter}.s1-tier,.s1-agreement{display:flex;flex-direction:column;gap:$space-3;font-size:15px;line-height:1.7;overflow-wrap:anywhere}.s1-copy{display:block;color:$color-text-secondary;font-size:13px;line-height:1.7;overflow-wrap:anywhere}.s1-reason{padding:$space-2 0;border-bottom:1px solid $color-border}</style>
